SELECT jsonb_build_object('settings',(SELECT to_jsonb(c) FROM zoi.booking_settings c WHERE workspace_id='053a5656-b19b-48a4-8721-65c4674f647c'),'listing',(SELECT jsonb_build_object('id',id,'slug',slug,'name',name,'publish_status',publish_status,'marketplace_status',marketplace_status,'workspace',owner_workspace_id) FROM zoi.listings WHERE id='e7b18e84-41cb-4b13-a591-2f1ed55ef4ff'),'slots',(SELECT jsonb_agg(to_jsonb(s)) FROM zoi.booking_slots s WHERE workspace_id='053a5656-b19b-48a4-8721-65c4674f647c'),'plans',(SELECT jsonb_agg(jsonb_build_object('id',id,'workspace_id',workspace_id,'actor_profile_id',actor_profile_id,'service_id',service_id,'resource_id',resource_id)) FROM zoi.booking_availability_plans WHERE workspace_id='053a5656-b19b-48a4-8721-65c4674f647c'),'foreign_keys',(SELECT jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'definition',pg_get_constraintdef(oid))) FROM pg_constraint WHERE contype='f' AND confrelid='zoi.listings'::regclass)) AS private_planner_cleanup_review;
